if v not in MIGRATIONS:
    raise ValueError(f"Missing migration for version {v}")
m = MIGRATIONS[v]

class QuarantineSnapshot:
    record: QuarantineRecord
    bounded_bytes: bytes
    source_identity_current: bool

    def __repr__(self) -> str:
        return f"QuarantineSnapshot(record={self.record!r}, bounded_bytes=<redacted>, source_identity_current={self.source_identity_current!r})"

class FilesystemBoundaryError(RuntimeError):
    """Content-free typed outer-boundary error."""

    def __init__(self, code: str) -> None:
        self.code = code
        super().__init__(code)

class FilesystemQuarantine:
    """Only E08 component that sees user paths; quarantine names are opaque."""

    def __init__(
        self,
        *,
        identity_hook: Callable[[Path], None] | None = None,
        digest_key: bytes,
        fingerprint_key_version: str = "vault-fingerprint-v1",
    ) -> None:
        self._objects: dict[str, _StoredObject] = {}
        self._identity_hook = identity_hook
        if len(digest_key) < 32 or not fingerprint_key_version:
            raise ValueError("A versioned vault-scoped fingerprint key is required")
        self._digest_key = digest_key
        self._fingerprint_key_version = fingerprint_key_version

    def intake(
        self,
        user_path: str | os.PathLike[str],
        *,
        profile: PlainTextResourceProfile,
        parser_identity: str,
        policy_lineage_id: str,
        declared_mime: str | None = None,
        declared_encoding: str | None = None,
    ) -> QuarantineRecord:
        path = Path(user_path)
        try:
            inspected = path.lstat()
        except OSError:
            raise FilesystemBoundaryError("source_unavailable") from None
        self._validate_regular(inspected)
        identity = self._identity(inspected)
        if self._identity_hook is not None:
            self._identity_hook(path)

        flags = os.O_RDONLY | getattr(os, "O_BINARY", 0)
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        try:
            descriptor = os.open(path, flags)
        except OSError:
            raise FilesystemBoundaryError("source_open_failed") from None
        try:
            opened = os.fstat(descriptor)
            self._validate_regular(opened)
            opened_identity = self._identity(opened)
            if self._stable_identity(opened_identity) != self._stable_identity(identity):
                raise FilesystemBoundaryError("source_identity_changed")
            self._verify_path(path, identity)
            chunks: list[bytes] = []
            total = 0
            while True:
                chunk = os.read(descriptor, min(READ_CHUNK, profile.maximum_original_bytes + 1 - total))
                if not chunk:
                    break
                chunks.append(chunk)
                total += len(chunk)
                if total > profile.maximum_original_bytes:
                    raise FilesystemBoundaryError("byte_limit_exceeded")
            final = os.fstat(descriptor)
            if self._identity(final) != opened_identity:
                raise FilesystemBoundaryError("source_identity_changed")
            self._verify_path(path, identity)
        finally:
            os.close(descriptor)

        bounded_bytes = b"".join(chunks)
        quarantine_id = "q-" + secrets.token_hex(16)
        source_candidate_id = "import-" + secrets.token_hex(16)
        source_version_id = source_candidate_id + "-v1"
        protected_ref = self._fingerprint_key_version + ":" + hmac.new(
            self._digest_key, bounded_bytes, hashlib.sha256
        ).hexdigest()
        record = QuarantineRecord(
            quarantine_id=quarantine_id,
            source_candidate_id=source_candidate_id,
            source_version_id=source_version_id,
            protected_digest_ref=protected_ref,
            byte_count=total,
            profile_id=profile.profile_id,
            parser_identity=parser_identity,
            policy_lineage_id=policy_lineage_id,
            declared_mime=declared_mime,
            declared_encoding=declared_encoding,
            processing_state="quarantined",
        )
        self._objects[quarantine_id] = _StoredObject(record, bounded_bytes, path, identity)
        return record

    def snapshot(self, quarantine_id: str) -> QuarantineSnapshot:
        stored = self._objects.get(quarantine_id)
        if stored is None:
            raise FilesystemBoundaryError("quarantine_unavailable")
        current = self._current_identity(stored.path) == stored.identity
        expected = self._fingerprint_key_version + ":" + hmac.new(
            self._digest_key, stored.bounded_bytes, hashlib.sha256
        ).hexdigest()
        if not hmac.compare_digest(expected, stored.record.protected_digest_ref):
            raise FilesystemBoundaryError("quarantine_integrity_failed")
        return QuarantineSnapshot(stored.record, stored.bounded_bytes, current)

    def transition(self, quarantine_id: str, state: str, rejection_reason: str | None = None) -> None:
        stored = self._objects.get(quarantine_id)
        if stored is None:
            raise FilesystemBoundaryError("quarantine_unavailable")
        stored.record = replace(
            stored.record, processing_state=state, rejection_reason=rejection_reason
        )

    def remove(self, quarantine_id: str) -> None:
        self._objects.pop(quarantine_id, None)

    def contains(self, quarantine_id: str) -> bool:
        return quarantine_id in self._objects

    def replace_bytes_for_test(self, quarantine_id: str, replacement: bytes) -> None:
        """Fault-injection hook: corruption must be detected, never accepted."""
        stored = self._objects[quarantine_id]
        stored.bounded_bytes = replacement

    @staticmethod
    def _identity(info: os.stat_result) -> FileIdentity:
        return FileIdentity(
            info.st_dev,
            info.st_ino,
            info.st_size,
            info.st_mtime_ns,
            info.st_ctime_ns,
            info.st_mode,
        )

    @classmethod
    def _verify_path(cls, path: Path, expected: FileIdentity) -> None:
        try:
            info = path.lstat()
            cls._validate_regular(info)
        except (OSError, FilesystemBoundaryError):
            raise FilesystemBoundaryError("source_identity_changed") from None
        if cls._stable_identity(cls._identity(info)) != cls._stable_identity(expected):
            raise FilesystemBoundaryError("source_identity_changed")

    @staticmethod
    def _stable_identity(identity: FileIdentity) -> tuple[int, int, int, int, int]:
        return (
            identity.device,
            identity.inode,
            identity.size,
            identity.modified_ns,
            identity.mode,
        )

    @staticmethod
    def _validate_regular(info: os.stat_result) -> None:
        attributes = getattr(info, "st_file_attributes", 0)
        if stat.S_ISLNK(info.st_mode) or attributes & REPARSE_POINT:
            raise FilesystemBoundaryError("link_or_reparse_rejected")
        if not stat.S_ISREG(info.st_mode):
            raise FilesystemBoundaryError("non_regular_file_rejected")

    @classmethod
    def _current_identity(cls, path: Path) -> FileIdentity | None:
        try:
            info = path.lstat()
            cls._validate_regular(info)
        except (OSError, FilesystemBoundaryError):
            return None
        return cls._identity(info)

class RetrievalStatus(StrEnum):
    OK = "ok"
    UNAVAILABLE = "unavailable"

class RetrievalOutcome:
    """Truthful retrieval outcome; unavailable never fabricates results."""

    status: str
    reason: str | None
    manifest: RetrievalManifest | None
    results: tuple[RetrievalResult, ...]

    @property
    def ok(self) -> bool:
        return self.status == RetrievalStatus.OK.value

class E09RetrievalService:
    """Builds, rebuilds and queries a disposable lexical projection."""

    def __init__(self, connection: Any, config: LexicalConfig | None = None) -> None:
        self.connection = connection
        self.config = config or LexicalConfig()
        self.projection: LexicalProjection | None = None

    def build(self) -> ProjectionManifest:
        """Build (or rebuild) the projection from current canonical data."""
        self.projection = build_lexical_projection(self.connection, self.config)
        return self.projection.manifest

    def rebuild(self) -> ProjectionManifest:
        return self.build()

    def drop(self) -> None:
        """Delete the disposable projection; canonical data is untouched."""
        self.projection = None

    def is_stale(self) -> bool:
        if self.projection is None:
            return True
        m = self.projection.manifest
        return (
            canonical_input_identity(self.connection) != m.canonical_input_identity
            or policy_identity(self.connection) != m.policy_identity
        )

    def is_corrupt(self) -> bool:
        return self.projection is not None and not projection_is_intact(self.projection)

    def retrieve(self, query: str, purpose: str = "local_lexical_retrieval") -> RetrievalOutcome:
        query_tokens = " ".join(tokenize(query, self.config))
        query_id = "e09-q-" + _digest((purpose, query, RETRIEVER_VERSION))[:12]

        def unavailable(reason: RetrievalUnavailableReason) -> RetrievalOutcome:
            return RetrievalOutcome(
                status=RetrievalStatus.UNAVAILABLE.value,
                reason=reason.value,
                manifest=RetrievalManifest(
                    query_id=query_id,
                    purpose=purpose,
                    query_text=query,
                    query_representation="lexical_tokens_v1",
                    query_version=query_tokens,
                    projection_manifest_id=(
                        self.projection.manifest.projection_id if self.projection else None
                    ),
                    canonical_cutoff=(
                        self.projection.manifest.canonical_cutoff if self.projection else None
                    ),
                    selected_ids=(),
                    scores=(),
                    policy_identity=(
                        self.projection.manifest.policy_identity if self.projection else ""
                    ),
                    retriever_version=RETRIEVER_VERSION,
                ),
                results=(),
            )

        if self.projection is None:
            return unavailable(RetrievalUnavailableReason.NO_PROJECTION)
        if self.projection.manifest.status != "ready":
            return unavailable(RetrievalUnavailableReason.PROJECTION_BLOCKED)
        if self.is_corrupt():
            return unavailable(RetrievalUnavailableReason.PROJECTION_CORRUPT)
        if self.is_stale():
            return unavailable(RetrievalUnavailableReason.PROJECTION_STALE)

        raw = retrieve(self.projection, query, self.config)
        expansions = relation_expansion(self.connection, [r.record_id for r in raw])
        results = tuple(
            RetrievalResult(
                record_id=r.record_id,
                version_id=r.version_id,
                kind=r.kind,
                score=r.score,
                matched_terms=r.matched_terms,
                relation_expansion=expansions.get(r.record_id, ()),
            )
            for r in raw
        )
        manifest = RetrievalManifest(
            query_id=query_id,
            purpose=purpose,
            query_text=query,
            query_representation="lexical_tokens_v1",
            query_version=query_tokens,
            projection_manifest_id=self.projection.manifest.projection_id,
            canonical_cutoff=self.projection.manifest.canonical_cutoff,
            selected_ids=tuple((r.record_id, r.version_id) for r in results),
            scores=tuple(r.score for r in results),
            policy_identity=self.projection.manifest.policy_identity,
            retriever_version=RETRIEVER_VERSION,
        )
        return RetrievalOutcome(RetrievalStatus.OK.value, None, manifest, results)

